/** Photos for a page: the listed groups in order, de-duplicated, offset so sibling pages lead with different shots. */
export function wdPhotos(groups: string[], n = 9, offset = 0): WdPhoto[] {
  const out: WdPhoto[] = [];
  for (const g of groups) {
    const all = WD_PHOTOS.filter((p) => p.group === g);
    const rot = all.length ? offset % all.length : 0;
    for (const p of [...all.slice(rot), ...all.slice(0, rot)]) if (!out.includes(p)) out.push(p);
  }
  return out.slice(0, n);
}
